		AdjacencyList adjDirected = new AdjacencyList(N, true);
		AdjacencyList adjNotDirected = new AdjacencyList(N, false);

		// adiciona arestas
		for(int i = 0; i < M; i++) {
			int nodeA = in.nextInt(), nodeB = in.nextInt(), weight = in.nextInt();
			adjDirected.addEdge(nodeA, nodeB, weight);
