class LinkedList {

    private Node head;
    private int size;

    public LinkedList() {
        this.head = null;
        this.size = 0;
    }

    public boolean isEmpty() {
        return this.head == null;
    }

    public void add(int v) {
        Node newNode = new Node(v);

        if (isEmpty())
            this.head = newNode;
        else {
            Node aux = head;
            while (aux.next != null)
                aux = aux.next;
            aux.next = newNode;
        }

        this.size += 1;
    }

    private int search(int value) {
        int i = 0;
        Node aux = head;
        while (aux != null && aux.value != value) {
            aux = aux.next;
            i++;
        }
        return (aux == null) ? -1 : i;
    }

    public boolean remove(int value) {

        if (!isEmpty()) {

            if (this.head.value == value) {
                this.head = this.head.next;
                this.size--;
                return true;
            }

            Node prev = null;
            Node aux = head;

            while (aux != null && aux.value != value) {
                prev = aux;
                aux = aux.next;
            }

            if (aux == null) return false;
            else {
                prev.next = aux.next;
                this.size--;
                return true;
            }

        }

        return false;


    }

    public boolean removeLast() {

        if (!isEmpty()) {

            if (this.head.next == null)
                this.head = null;
            else {
                Node prev = null;
                Node aux = head;

                while(aux.next != null) {
                    prev = aux;
                    aux = aux.next;
                }

                prev.next = null;
            }
            this.size--;
            return true;
        }
        return false;

    }

    public int size() {
        return this.size;
    }

